/// <summary>A real local HTTP server standing in for the provider; records the request it receives.</summary>
internal sealed class StubProvider : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly Task loop;

    public StubProvider(int status, string? body, string contentType = "application/json")
    {
        int port;
        using (var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0))
        {
            probe.Start();
            port = ((IPEndPoint)probe.LocalEndpoint).Port;
        }
        BaseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add($"{BaseAddress}/");
        listener.Start();
        loop = Task.Run(async () =>
        {
            var ctx = await listener.GetContextAsync();
            using var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8);
            Received = new ReceivedRequest(ctx.Request.HttpMethod, ctx.Request.Url!.AbsolutePath,
                ctx.Request.ContentType, await reader.ReadToEndAsync());
            ctx.Response.StatusCode = status;
            if (body is not null)
            {
                ctx.Response.ContentType = contentType;
                var bytes = Encoding.UTF8.GetBytes(body);
                await ctx.Response.OutputStream.WriteAsync(bytes);
            }
            ctx.Response.Close();
        });
    }

    public Uri BaseAddress { get; }

    public ReceivedRequest? Received { get; private set; }

    public void Dispose()
    {
        listener.Close();
        try { loop.Wait(TimeSpan.FromSeconds(2)); } catch (AggregateException) { }
    }
}

