    public async Task A_declined_answer_is_read_as_declined()
    {
        using var provider = new StubProvider(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        using var provider = new StubProvider(200, """{"id":"a1","status":"approved","risk":{"score":3}}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(provider));
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_with_an_error_body()
    {
        using var provider = new StubProvider(402, """{"error":"card_refused"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
    }

    [Fact]
    public async Task A_402_refusal_without_a_body_is_a_decline()
    {
        using var provider = new StubProvider(402, null);
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task A_rejected_request_or_provider_failure_is_an_error_not_a_decline(int status)
    {
        using var provider = new StubProvider(status, """{"error":"nope"}""");
        await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(provider));
    }

    [Fact]
    public async Task A_body_that_is_not_json_is_an_error()
    {
        using var provider = new StubProvider(200, "<html>oops</html>", "text/html");
        await Assert.ThrowsAnyAsync<Exception>(() => Authorize(provider));
    }

    [Fact]
    public async Task An_unknown_status_value_is_never_treated_as_approved()
    {
        using var provider = new StubProvider(200, """{"status":"pending"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_treated_as_approved()
    {
        using var provider = new StubProvider(200, """{"decision":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
    }
}
